namespace ghidra.app.plugin.core.debug.gui.tracermi.connection.tree;






using ghidra.app.plugin.core.debug.gui;
using ghidra.app.plugin.core.debug.gui.tracermi.connection;
using ghidra.debug.api.target;
using ghidra.debug.api.tracermi;
using resources;

public class TraceRmiConnectionNode : AbstractTraceRmiManagerNode {
	private static readonly Icon ICON = DebuggerResources.ICON_CONNECTION;
	private static readonly Icon ICON_TX = new MultiIcon(ICON, ICON_TX_OVERLAY);

	private TraceRmiConnection connection;
	private Map<Target, TraceRmiTargetNode> targetNodes = new();

	public TraceRmiConnectionNode(TraceRmiConnectionManagerProvider provider,
			TraceRmiConnection connection) {
		// TODO: Can the connector identify/describe itself for this display?
		super(provider, "Connected: " + connection.getRemoteAddress());
		this.connection = connection;
	}

	/* @Override */
	public string getDisplayText() {
		try {
			return connection.getDescription() + " at " + connection.getRemoteAddress();
		}
		catch (Exception e) {
			provider.cleanConnectionNode(this);
			return "Error: " + e;
		}
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return connection.isBusy() ? ICON_TX : ICON;
	}

	/* @Override */
	public string getToolTip() {
		try {
			return "Trace RMI Connection to " + connection.getDescription() + " at " +
				connection.getRemoteAddress();
		}
		catch (Exception e) {
			return "Error: " + e;
		}
	}

	/* @Override */
	public bool isLeaf() {
		return false;
	}

	private TraceRmiTargetNode newTargetNode(Target target) {
		return new TraceRmiTargetNode(provider, this, target);
	}

	private TraceRmiTargetNode addTargetNode(Target target) {
		TraceRmiTargetNode node;
		lock (targetNodes) {
			node = targetNodes.computeIfAbsent(target, this.newTargetNode);
		}
		addNode(node);
		return node;
	}

	private void removeTargetNode(Target target) {
		TraceRmiTargetNode node;
		lock (targetNodes) {
			node = targetNodes.remove(target);
		}
		if (node == null) {
			return;
		}
		removeNode(node);
	}

	public TraceRmiTargetNode targetPublished(Target target) {
		return addTargetNode(target);
	}

	public void targetWithdrawn(Target target) {
		removeTargetNode(target);
	}

	public TraceRmiConnection getConnection() {
		return connection;
	}
}
